def transform(grid):
    h, w = len(grid), len(grid[0])
    # Treat each 4-connected component as a rigid object and let objects
    # settle into the bottom of the grid, keeping their original columns.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            comps.append((color, cells))

    out = [[0] * w for _ in range(h)]
    # Bottom objects first; choose the lowest collision-free vertical translation.
    comps.sort(key=lambda item: max(r for r, c in item[1]), reverse=True)
    for color, cells in comps:
        drop = 0
        while True:
            candidate = [(r + drop + 1, c) for r, c in cells]
            if any(r >= h for r, c in candidate) or any(out[r][c] != 0 for r, c in candidate):
                break
            drop += 1
        for r, c in cells:
            out[r + drop][c] = color
    return out
